---选择按钮点击回调
function CardProgressionEquipmentEngraveDialog:BtnChooseOnCLickHandler()
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardId = self:GetSelectedCardId()
    if cardId == 0 then
        cardId = nil
    end
    CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamCardChoose, {
        chooseCardStatu = Constants.ChooseCardStatus.Custom,
        customCardDojos = cardComp:GetAllCardTable(),
        customSelectIds = {cardId},
        customLeastNum  = 1,
        customLimitNum  = 1,
        ---@param newSelectIds string[]
        confirmCb = function(newSelectIds)
            self:SetSelectedCardId(newSelectIds[1])
        end,
        closeCb = function()
            self:RefreshView()
        end
    })
end

---刻印按钮点击回调
function CardProgressionEquipmentEngraveDialog:BtnEngraveOnClickHandler()
    if self:GetSelectedCardId() == 0 then
        GameUtils.Toast(localize('请选择战斗员'))
        return 
    end
    
    local consume = EquipUtils.GetEngraveConsume()
    local _, errTip = GoodsUtils.CheckGoodConsume(consume)
    if errTip then
        GameUtils.Toast(errTip)
        return
    end

    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComp:GetCardByConfId(self:GetSelectedCardId())
    local cardVo = CardConfMgrIns:GetCardByRefId(cardDojo.cardId)

    GameUtils.SecondConfirm(localize('刻印后，只有<color=#e71f55>[_name_]</color>穿戴时，刻印效果才生效，是否确认？', {_name_ = cardVo.name}), function()
        CardProgressionMgr:RequestOverseaEquipmentEngrave({playerEquipmentId = self:GetEquipDojo().id, playerCardId = cardDojo.id}, consume)
        self:CloseDialog()  
    end, nil, nil, 1)
end

---提示按钮点击回调
function CardProgressionEquipmentEngraveDialog:BtnExplainOnClickHandler()
    CfUtils.ShowModuleToast(Constants.SystemToggleIds.Id3208)
end
