--region private
---刷新界面
function CardProgressionEquipmentEngraveDialog:RefreshView()
    self:RefreshEquipmentGoods()
    self:RefreshCardNode()
    self:RefreshAttr()
    self:RefreshConsume()
    self:RefreshButton()
end

---刷新装备道具
function CardProgressionEquipmentEngraveDialog:RefreshEquipmentGoods()
    local equipDojo = self:GetEquipDojo()
    local goodsVo = GoodsConfMgrIns:GetGoodsVoById(equipDojo.equipmentId)

    CfUtils.FillText(self.TextDesc, goodsVo.name)

    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end
end

---刷新卡牌节点
function CardProgressionEquipmentEngraveDialog:RefreshCardNode()
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardId = self:GetSelectedCardId()
    if cardId == 0 then
        CfUtils.SetActive(self.Empty, true)
        CfUtils.SetActive(self.Content, false)
        return 
    end

    CfUtils.SetActive(self.Empty, false)
    CfUtils.SetActive(self.Content, true)

    ---@type Engine.Modules.LuaBehaviour
    local headNode = GetLuaBehaviour(self.CommonSmallHeadNode.gameObject, CardHeadNodePath)
    if isNull(headNode.Env) then
        headNode:Init()
    end
    local cardDojo = cardComp:GetCardByConfId(cardId)
    headNode.Env:FreshNode(cardDojo)
    headNode.Env:SetCallBack(Bind(self, self.BtnChooseOnCLickHandler))
end

---刷新属性
function CardProgressionEquipmentEngraveDialog:RefreshAttr()
    local equipDojo = self:GetEquipDojo()
    ---@type EquipVo
    local equipVo = CardConfMgrIns:GetEquipVoById(equipDojo.equipmentId)
    local mainAttrAdditionId = equipDojo.mainAttrId
    local attrAdditionVo = CardConfMgrIns:GetBasicAttrAdditionById(mainAttrAdditionId)
    local mainEquipAttrVo = CardConfMgrIns:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = CardConfMgrIns:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrVo = CardConfMgrIns:GetBasicAttr(attrAddVo.attrId)

    CfUtils.FillImage(self.ImgAttributeIcon, attrVo.icon)
    CfUtils.FillText(self.TxtAttack, attrAdditionVo.attrAdditionName)
    CfUtils.FillText(self.TxtNumberOld, attribute_format(attrAddVo.isConversion, equipDojo.mainAttrNum))
    local addition = checkNumber(CardConfMgrIns:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveAddiRate))
    local value = tonumber(equipDojo.mainAttrNum) * (addition + 1)
    CfUtils.FillText(self.TxtNumberNew, attribute_format(attrAddVo.isConversion, value))
end

---刷新消耗
function CardProgressionEquipmentEngraveDialog:RefreshConsume()
    local consume = EquipUtils.GetEngraveConsumeMaterial()
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, CommonGoodsListLightPath)
    scr:FreshBaseUI(consume, false, false, true, true)

    CfUtils.SetActive(self.CommonBtnConsumePop, true)
    local consumeGold = EquipUtils.GetEngraveConsumeGold()
    CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, consumeGold[1].goodsId, consumeGold[1].goodsNum, false, false)
end

---刷新按钮状态
function CardProgressionEquipmentEngraveDialog:RefreshButton()
    local isChoose = self:GetSelectedCardId() > 0
    CfUtils.SetActive(self.CommonBtnConsumePop, isChoose)
    local font = isChoose and 'B1' or "B17"
    self.FontStyleButton:ResetFontStyle(font)
end

---关闭界面
function CardProgressionEquipmentEngraveDialog:CloseDialog()
    UIModule.CloseDialog(self.controller)
end
